window.POETRY_REGISTER("v5-strict-8-10-0-d5581200e237.js",{"poems":[[3110,2],[12616,2],[55668,2],[59081,7],[64226,7],[116979,7],[134635,7],[136830,7],[146453,7],[155955,7],[169925,7],[178065,7],[187920,7],[221364,7],[230810,7],[233415,7],[233438,7],[250736,7],[267739,7],[270522,7],[271947,7],[271968,7],[272160,7],[273471,7],[284800,7],[285837,7],[287671,7],[288130,7],[288138,7],[293218,7],[293222,7],[293290,7],[293958,7],[295324,7],[301663,7],[306909,7],[318077,7],[332807,9],[335881,9],[347201,9],[373007,10],[378236,10],[382202,0],[420355,8],[422351,8],[425774,8],[451830,8],[453910,8],[455818,8],[460325,8],[466698,8],[467647,8],[467899,8],[539129,8],[540516,8],[540569,8],[553459,8],[573757,8],[589803,8],[595834,8],[595847,8],[614596,8],[633558,15],[636035,15],[647954,15],[650074,5],[682350,5],[689565,5],[692471,5],[716038,5]],"pairs":[["我自顾悠悠而若云","又安能保君皓皓之如雪",0],["使我不得尔之扶持","灭迹于君山湖上之青峰",1],["不知方干唐末不第","死后得赐一官以慰冥魂",2],["叹笑筵歌席轻抛亸","背孤城几舍烟村停画舸",3],["矧清风明月非钱买","休追念金马玉堂心胆碎",4],["世方好柔兮我方刚","彼为辕下驹兮我方鹰扬",5],["夫是之谓馿手佛脚","而真得无学于保宁者也",6],["盖有有其实而不受","亦有无其实而固求者也",7],["不能坐穷庐运筹算","胡为乎骑马试剑轻其躯",8],["岂平章佛法之宰相","乃檀越丛林之韵人也耶",9],["千峰来南兮万马奔","翠麓却立兮如饮江之鼋",10],["径山今日内实告报","汝等诸人切忌钻龟打瓦",11],["跼蹐胁息以休影兮","石壁屹立而不可以攀缘",12],["摘玉李而弄金波兮","遨嬉乎倒景有无之蒙鸿",13],["发之新兮志偕而堕","非金玉之人兮孰振吾过",14],["聊淹留兮岁聿其暮","鼓丝桐兮从夫君而与归",15],["昔芬馨兮袭人旖旎","今质存兮已魄然而少气",16],["视鸾台凤阁为蘧庐","百万买宅亦梦幻泡影沤",17],["指余以南峰石壁记","授余以红铅黑汞大丹头",18],["是为广智九世之孙","啸岩一枝不致寥寞者矣",19],["若夫屈伸则有时也","而岂以是为富贵之资也",20],["即此帖之藏于宝真","殆所谓同工而异曲者兮",21],["盖当心摹手追之时","已有之死不顾之遗风矣",22],["扪参历井兮水云乡","如辽东之返兮华表飞扬",23],["君不见煮豆燃豆萁","斯人者斗米尺布渠岂羞",24],["说一句痛处针便住","教我行持片饷间骨毛寒",25],["君之来兮鹤自九皋","驾以去兮渺天地而逍遥",26],["万山蟠兮有宅一区","吁嗟吉士兮心古而色愉",27],["指期颐兮二竖立病","既偕老兮亦相继而长徂",27],["岁律残兮北风正南","渡梅花之桥兮龙㡛镳镳",28],["瑞岩今夜事不获已","未免擘破面门开个方便",29],["诸人若果疑情未决","但向冷地里摸索鼻孔看",30],["不知赚了多少衲僧","至今八错七差三马九乱",31],["人人只知骤步登高","往往蹉过自家稳密田地",32],["秋风萧飒兮白露晞","五十年闺闼兮甯识马嘶",33],["此所谓乐闲之道人","赞之者本堂老夫之醉墨",34],["诸人痛处山僧能忍","山僧痛处诸人欲忍不能",35],["若是觑不破跳不出","切须翻天覆地离巢越窟",36],["曾雅称量金结胜游","信人间无点事可挂心头",37],["肯不肯疾些儿通报","休直到教担阁得天明了",38],["云山之间七十一峰","下有七曲横江子房赤松",39],["噫嘘嚱安得快剪刀","剪取云梦竹䨲毫束作笔",40],["独不记臣言良与忠","胡为乎会须杀此田舍翁",41],["阴阳易位时不当兮","怀信侘傺忽乎吾将行兮",42],["母乐泄泄子乐融融","不比杨柳枝零落同秋蓬",43],["山中之人兮云为徒","飘摇太虚中其迹安可拘",44],["神窅窅兮思深靖止","目不睨兮谅正直乎眸子",45],["我作歌兮告尔后昆","尔燕而聚兮无忘尔世勋",46],["巨鳌戴之与波下上","三十五莲峰照耀云中辉",47],["衔书献瑞降神德门","乃为少宰之子司徒之孙",48],["咄嗟胡为乎东复西","君不见青松女萝自相依",49],["无蔽芾以藏其朱颜","绛灌将相大臣自愧其妍",50],["我不能六翮飞上天","又不能摧眉折腰贵人前",51],["何必要什袭藏名山","何必要咸阳市上千金悬",52],["洪潦纵横兮泥途深","车不得轨行兮马力不任",53],["使蓬莱可得而至兮","吾又何惮夫渺漭之风波",54],["哀响入微兮意未已","激流风兮杳不知其所止",55],["但能和地天平上下","自然句者堪伸萌者堪架",56],["巍巍乎万峰之阁兮","乃在句践之国梵王之家",57],["人皆有母而我独无","嗟我之生曾不如彼慈乌",58],["人皆有子而母独亡","嗟母之生曾不如彼空桑",58],["有登斯堂慕美人兮","彼美人之诚意足以遁世",59],["恩衔义结兮草木知","将感召而来兮天朝羽仪",60],["何必要什袭藏名山","何必要咸阳市上千金悬",61],["东藏郓欢龟阴之田","西虞芮倒影晶天无表里",62],["苟用人尽当其职兮","岂徒继东晋南宋之遗芳",63],["况芙蕖千顷非钱买","休还恨犀箸玉盘消息绝",64],["儿媳妇娶了邑姜女","绣房里习就夺槊并滚叉",65],["春秋出头有二十国","一霎时七雄割据把兵鏖",65],["东宫里杨广杀了父","积作的扬州看花把命化",65],["叹岁寒残雪谁堪语","换苍苔旧步荒江桥上路",66],["向吴云深处诗囊载","冲潮落风静月中闻紫佩",67],["正废池乔木春光浅","费商量好鸟枝头千万啭",68],["忽轻说乘扁舟去休","也曾念共绣阁论文人否",69]]});
